try:
    import unittest2 as unittest
except ImportError:
    import unittest  # type: ignore

from taf.cloud.cbam.schemas.v4.vnf_instance import VnfInfo


class TestVnfInstance(unittest.TestCase):

    def test_createObject(self):
        params = {'id': 'id',
                  'vnfInstanceName': 'vnfInstanceName',
                  'vnfInstanceDescription': 'vnfInstanceDescription',
                  'vnfdId': 'vnfdId',
                  'vnfProvider': 'vnfProvider',
                  'vnfProductName': 'vnfProductName',
                  'vnfSoftwareVersion': 'vnfSoftwareVersion',
                  'vnfdVersion': 'vnfdVersion',
                  'vnfPkgId': 'vnfPkgId',
                  'vimConnectionInfo': 'vimConnectionInfo',
                  'instantiationState': 'instantiationState',
                  'instantiatedVnfInfo': 'instantiatedVnfInfo',
                  'vnfConfigurableProperties': 'vnfConfigurableProperties',
                  'extensions': 'extensions',
                  'metadata': 'metadata',
                  '_links': '_links',
                  'operationId': 'operationId'}

        vnf_object = VnfInfo(id=params['id'],
                             name=params['vnfInstanceName'],
                             description=params['vnfInstanceDescription'],
                             vnfd_id=params['vnfdId'], vnf_provider=params['vnfProvider'],
                             vnf_product_name=params['vnfProductName'],
                             vnf_software_version=params['vnfSoftwareVersion'],
                             vnfd_version=params['vnfdVersion'],
                             vnf_pkg_id=params['vnfPkgId'],
                             vim_connection_info=params['vimConnectionInfo'],
                             instantiation_state=params['instantiationState'],
                             instantiated_vnf_info=params['instantiatedVnfInfo'],
                             vnf_configurable_properties=params['vnfConfigurableProperties'],
                             extensions=params['extensions'],
                             metadata=params['metadata'],
                             links=params['_links'],
                             operation_id=params['operationId'])

        self.assertEqual(vnf_object.id, params['id'])
        self.assertEqual(vnf_object.name, params['vnfInstanceName'])
        self.assertEqual(vnf_object.description, params['vnfInstanceDescription'])
        self.assertEqual(vnf_object.vnfd_id, params['vnfdId'])
        self.assertEqual(vnf_object.vnf_provider, params['vnfProvider'])
        self.assertEqual(vnf_object.vnf_product_name, params['vnfProductName'])
        self.assertEqual(vnf_object.vnf_software_version, params['vnfSoftwareVersion'])
        self.assertEqual(vnf_object.vnfd_version, params['vnfdVersion'])
        self.assertEqual(vnf_object.vnf_pkg_id, params['vnfPkgId'])
        self.assertEqual(vnf_object.vim_connection_info, params['vimConnectionInfo'])
        self.assertEqual(vnf_object.instantiation_state, params['instantiationState'])
        self.assertEqual(vnf_object.instantiated_vnf_info, params['instantiatedVnfInfo'])
        self.assertEqual(vnf_object.vnf_configurable_properties, params['vnfConfigurableProperties'])
        self.assertEqual(vnf_object.extensions, params['extensions'])
        self.assertEqual(vnf_object.metadata, params['metadata'])
        self.assertEqual(vnf_object.links, params['_links'])
        self.assertEqual(vnf_object.operation_id, params['operationId'])

    def test_createObject_FromResponseDict(self):
        response = {'id': 'id',
                    'vnfInstanceName': 'vnfInstanceName',
                    'vnfInstanceDescription': 'vnfInstanceDescription',
                    'vnfdId': 'vnfdId',
                    'vnfProvider': 'vnfProvider',
                    'vnfProductName': 'vnfProductName',
                    'vnfSoftwareVersion': 'vnfSoftwareVersion',
                    'vnfdVersion': 'vnfdVersion',
                    'vnfPkgId': 'vnfPkgId',
                    'vimConnectionInfo': 'vimConnectionInfo',
                    'instantiationState': 'instantiationState',
                    'instantiatedVnfInfo': 'instantiatedVnfInfo',
                    'vnfConfigurableProperties': 'vnfConfigurableProperties',
                    'extensions': 'extensions',
                    'metadata': 'metadata',
                    '_links': '_links',
                    'operationId': 'operationId'}

        vnf_object = VnfInfo.from_response_dict(response)
        self.assertEqual(vnf_object.id, response['id'])
        self.assertEqual(vnf_object.name, response['vnfInstanceName'])
        self.assertEqual(vnf_object.description, response['vnfInstanceDescription'])
        self.assertEqual(vnf_object.vnfd_id, response['vnfdId'])
        self.assertEqual(vnf_object.vnf_provider, response['vnfProvider'])
        self.assertEqual(vnf_object.vnf_product_name, response['vnfProductName'])
        self.assertEqual(vnf_object.vnf_software_version, response['vnfSoftwareVersion'])
        self.assertEqual(vnf_object.vnfd_version, response['vnfdVersion'])
        self.assertEqual(vnf_object.vnf_pkg_id, response['vnfPkgId'])
        self.assertEqual(vnf_object.vim_connection_info, response['vimConnectionInfo'])
        self.assertEqual(vnf_object.instantiation_state, response['instantiationState'])
        self.assertEqual(vnf_object.instantiated_vnf_info, response['instantiatedVnfInfo'])
        self.assertEqual(vnf_object.vnf_configurable_properties, response['vnfConfigurableProperties'])
        self.assertEqual(vnf_object.extensions, response['extensions'])
        self.assertEqual(vnf_object.metadata, response['metadata'])
        self.assertEqual(vnf_object.links, response['_links'])
        self.assertEqual(vnf_object.operation_id, response['operationId'])

    def test_createObject_AsDict(self):
        response = {'id': 'id',
                    'vnfInstanceName': 'vnfInstanceName',
                    'vnfInstanceDescription': 'vnfInstanceDescription',
                    'vnfdId': 'vnfdId',
                    'vnfProvider': 'vnfProvider',
                    'vnfProductName': 'vnfProductName',
                    'vnfSoftwareVersion': 'vnfSoftwareVersion',
                    'vnfdVersion': 'vnfdVersion',
                    'vnfPkgId': 'vnfPkgId',
                    'vimConnectionInfo': 'vimConnectionInfo',
                    'instantiationState': 'instantiationState',
                    'instantiatedVnfInfo': 'instantiatedVnfInfo',
                    'vnfConfigurableProperties': 'vnfConfigurableProperties',
                    'extensions': 'extensions',
                    'metadata': 'metadata',
                    '_links': '_links',
                    'operationId': 'operationId'}

        vnf_object = VnfInfo.from_response_dict(response)
        vnf_dict = vnf_object.as_dict()
        for k, v in response.items():
            with self.subTest():
                self.assertEqual(vnf_dict[k], response[v])
